module pulse_detect(
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

    reg [1:0] pulse_level1;
    reg [1:0] pulse_level2;

    parameter s0 = 2'b00;
    parameter s1 = 2'b01;
    parameter s2 = 2'b10;
    parameter s3 = 2'b11;

    // combinational logic for data_out
    assign data_out = (pulse_level2 == s2) && (data_in == 1'b0);

    // sequential logic for pulse_level1
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n)
            pulse_level1 <= s0;
        else
            pulse_level1 <= pulse_level2;
    end

    // combinational logic for pulse_level2
    always @(*) begin
        case (pulse_level1)
            s0: begin
                if (data_in == 1'b0)
                    pulse_level2 = s1;
                else
                    pulse_level2 = s0;
            end
            s1: begin
                if (data_in == 1'b1)
                    pulse_level2 = s2;
                else
                    pulse_level2 = s1;
            end
            s2: begin
                if (data_in == 1'b0)
                    pulse_level2 = s3;
                else
                    pulse_level2 = s0;
            end
            s3: begin
                if (data_in == 1'b1)
                    pulse_level2 = s2;
                else
                    pulse_level2 = s1;
            end
            default: pulse_level2 = s0;
        endcase
    end

endmodule
